		t.Fatalf("empty version: %v", err)
	}
	if err := s.Report("dev-1", 1, base, "1.1", json.RawMessage(`[1]`)); !errors.Is(err, ErrInvalidConfig) {
		t.Fatalf("bad config: %v", err)
	}

