	// 离线期间仍能修改期望
	if _, err := s.UpdateDesired("dev-1", "op", base.Add(time.Minute), 1, json.RawMessage(`{"mode":"eco"}`)); err != nil {
		t.Fatalf("update while offline: %v", err)
