243	// TestDiffMixedNumericPaths 两份配置中相等与不等数字同时存在时，
244	// 结果只包含实际不同的路径，按 JSON Pointer 字典序返回，且每条差异
245	// 携带的双方值与对应字段一一匹配（含高精度数字原样保留）。
246	func TestDiffMixedNumericPaths(t *testing.T) {
247		s, _ := setupDiffDevice(t,
248			json.RawMessage(`{
249				"a": 1000,
250				"b": 9007199254740992,
251				"c": 0.0001,
252				"d": 7,
253				"e": {"x": 0.10000000000000000001, "y": 1000},
254				"f": [1, 2],
255				"g": 3
256			}`),
257			json.RawMessage(`{
258				"a": 1e3,
259				"b": 9007199254740993,
260				"c": 1e-4,
261				"d": 7,
262				"e": {"x": 0.10000000000000000002, "y": 1000.00},
263				"f": [1, 2],
264				"g": "3"
265			}`),
266		)
267		diffs, err := s.Diff("dev-num")
268		if err != nil {
269			t.Fatal(err)
270		}
271		want := []struct {
272			path              string
273			desired, reported string
274		}{
275			{"/b", "9007199254740992", "9007199254740993"},
276			{"/e/x", "0.10000000000000000001", "0.10000000000000000002"},
277			{"/g", "3", `"3"`},
278		}
279		if len(diffs) != len(want) {
280			t.Fatalf("want %d diffs, got %+v", len(want), diffs)
281		}
282		for i, w := range want {
283			e := diffs[i]
284			if e.Path != w.path {
285				t.Fatalf("diff[%d] path: want %s got %s (full: %+v)", i, w.path, e.Path, diffs)
286			}
287			if !e.DesiredExists || !e.ReportedExists {
288				t.Fatalf("%s existence flags: %+v", w.path, e)
289			}
290			if string(e.Desired) != w.desired || string(e.Reported) != w.reported {
291				t.Fatalf("%s values: want %s/%s got %s/%s",
292					w.path, w.desired, w.reported, e.Desired, e.Reported)
293			}
294			// /b、/g 在期望写入时（reported 为空对象）即已存在；而此时整个 /e
295			// 子树在上报侧缺失，差异只记在 /e（不下钻），所以 /e/x 是上报后
296			// 双方都有 /e 时才首次出现，时间为上报时刻 base+1m。
297			wantSince := base
298			if e.Path == "/e/x" {
299				wantSince = base.Add(time.Minute)
300			}
301			if !e.Since.Equal(wantSince) {
302				t.Fatalf("%s since: want %v got %v", w.path, wantSince, e.Since)
303			}
304		}
305	}
306	
307	// TestDiffDoesNotMutateState Diff 是只读查询：不得改写设备保存的期望/上报
308	// 配置（包括其中数字的原始写法），不得增加修订号或审计记录；再次读取
309	// 仍看到原先提交的完整内容。
310	func TestDiffDoesNotMutateState(t *testing.T) {
311		desired := json.RawMessage("{\n  \"big\": 9007199254740992,\n  \"same\": 1000.00\n}")
312		reported := json.RawMessage(`{"same":1e3,"big":9007199254740993}`)
313		s, _ := setupDiffDevice(t, desired, reported)
314	
315		before, err := s.Get("dev-num")
316		if err != nil {
317			t.Fatal(err)
318		}
319		recsBefore, err := s.Audit("dev-num")
320		if err != nil {
321			t.Fatal(err)
322		}
323	
324		for i := 0; i < 3; i++ {
325			diffs, err := s.Diff("dev-num")
326			if err != nil {
327				t.Fatal(err)
328			}
329			if len(diffs) != 1 || diffs[0].Path != "/big" {
330				t.Fatalf("iteration %d: %+v", i, diffs)
331			}
332		}
333	
334		after, err := s.Get("dev-num")
335		if err != nil {
336			t.Fatal(err)
337		}
338		// 原始提交内容（含空白与数字写法）逐字节保留
339		if !bytes.Equal(after.Desired, desired) {
340			t.Fatalf("desired rewritten:\nbefore: %s\nafter:  %s", desired, after.Desired)
341		}
342		if !bytes.Equal(after.Reported, reported) {
343			t.Fatalf("reported rewritten:\nbefore: %s\nafter:  %s", reported, after.Reported)
344		}
345		if after.Revision != before.Revision {
346			t.Fatalf("revision changed: %d -> %d", before.Revision, after.Revision)
347		}
348		if after.Revision != 1 {
349			t.Fatalf("revision should still be 1, got %d", after.Revision)
350		}
351		recsAfter, err := s.Audit("dev-num")
352		if err != nil {
353			t.Fatal(err)
354		}
355		if len(recsAfter) != len(recsBefore) {
356			t.Fatalf("audit records changed: %d -> %d", len(recsBefore), len(recsAfter))
357		}
358		// 审计中保存的配置原文同样未被数字归一化
359		if !bytes.Equal(recsAfter[0].After, desired) {
360			t.Fatalf("audit after rewritten: %s", recsAfter[0].After)
361		}
362	}
363	
364	// TestDiffReturnedValuesAreIsolated 调用方篡改 Diff 返回的 RawMessage
365	// 不影响后续查询结果。
366	func TestDiffReturnedValuesAreIsolated(t *testing.T) {
367		s, _ := setupDiffDevice(t,
368			json.RawMessage(`{"big":9007199254740992}`),
369			json.RawMessage(`{"big":9007199254740993}`),
370		)
371		diffs, _ := s.Diff("dev-num")
372		diffs[0].Desired[0] = '1'
373		diffs[0].Reported[0] = '1'
374		diffs2, _ := s.Diff("dev-num")
375		if string(diffs2[0].Desired) != "9007199254740992" || string(diffs2[0].Reported) != "9007199254740993" {
376			t.Fatalf("stored diff values mutated by caller: %+v", diffs2[0])
377		}
378	}
